def fizz_buzz(n):
    # will hold the final list of strings, one per number
    result = []
    # walk through every number from 1 to n, inclusive
    for i in range(1, n + 1):
        # check the combined case first, or Fizz/Buzz would fire alone
        if i % 15 == 0:
            result.append("FizzBuzz")   # divisible by both 3 and 5
        elif i % 3 == 0:
            result.append("Fizz")       # divisible by 3 only
        elif i % 5 == 0:
            result.append("Buzz")       # divisible by 5 only
        else:
            result.append(str(i))       # not divisible by 3 or 5, keep the number
    return result                       # list of n strings, ready to print


if __name__ == "__main__":
    n = 15
    for s in fizz_buzz(n):
        print(s)

