import java.util.*;

public class Main {
    List<String> fizzBuzz(int n) {
        // will hold the final list of strings, one per number
        List<String> result = new ArrayList<>();
        // walk through every number from 1 to n, inclusive
        for (int i = 1; i <= n; i++) {
            // check the combined case first, or Fizz/Buzz would fire alone
            if (i % 15 == 0) {
                result.add("FizzBuzz");     // divisible by both 3 and 5
            } else if (i % 3 == 0) {
                result.add("Fizz");         // divisible by 3 only
            } else if (i % 5 == 0) {
                result.add("Buzz");         // divisible by 5 only
            } else {
                result.add(String.valueOf(i)); // not divisible by 3 or 5, keep the number
            }
        }
        return result;                      // list of n strings, ready to print
    }

    public static void main(String[] args) {
        int n = 15;
        Main solution = new Main();
        for (String s : solution.fizzBuzz(n)) {
            System.out.println(s);
        }
    }
}

